//! Validation harness: original shipping Sim role, ordinary game operations only.
use mycity_core::{venue_runtime::Command as V,facility_authority::Command as F,continuous_supply::Command as S,time_capacity::{Command as C,Registration,Unit},timeline::Command as T,transaction::{Action,Caller,Envelope,Resource}};
use mycity_headless::{sim_client::Client,sim_host::{Command,Event},normal_pool};
use mycity_storage::Store;
use std::{path::{Path,PathBuf},fs,fs::OpenOptions,io::Write,time::Duration};
fn next(c:&mut Client,p:&Path)->Event{let e=c.next(Duration::from_secs(15)).unwrap();writeln!(OpenOptions::new().append(true).create(true).open(p.join("events.jsonl")).unwrap(),"{}",serde_json::to_string(&e).unwrap()).unwrap();e}
fn envelope(s:&Store,a:Action)->Envelope{Envelope{world:1,branch:1,operation_id:s.committed_sequence()+1,expected_revision:s.engine().unwrap().world().view().revision,actions:vec![a]}}
fn a(command:C)->Action{Action::TimeCapacity{command}}
fn apply_as(s:&mut Store,caller:Caller,action:Action){let e=envelope(s,action);let out=s.execute(caller,e).unwrap();assert!(out.model.is_ok(),"{out:?}");}
fn apply(s:&mut Store,action:Action){apply_as(s,Caller::System,action);}
fn copy(source:&Path,dest:&Path){fs::create_dir(dest).unwrap();for entry in fs::read_dir(source).unwrap(){let entry=entry.unwrap();let out=dest.join(entry.file_name());if entry.file_type().unwrap().is_dir(){copy(&entry.path(),&out);}else{fs::copy(entry.path(),&out).unwrap();assert_eq!(fs::read(entry.path()).unwrap(),fs::read(out).unwrap());}}}
fn remote(c:&mut Client,p:&Path,id:u64,reference:&mut Store,action:Action)->Envelope{let e=envelope(reference,action);c.submit(id,Command::Execute{envelope:e.clone()}).unwrap();let out=next(c,p);assert!(out.payload["Ok"]["model"].get("Ok").is_some(),"{out:?}");assert!(reference.execute(Caller::System,e.clone()).unwrap().model.is_ok());e}
fn advance(c:&mut Client,p:&Path,id:&mut u64,reference:&mut Store,target:u64){for _ in 0..64{remote(c,p,*id,reference,Action::Timeline{command:T::Advance{target,limit:32}});*id+=1;if reference.engine().unwrap().timeline().unwrap().progress.target.is_none(){assert_eq!(reference.engine().unwrap().timeline().unwrap().progress.last_complete,target);return;}}panic!("finite original advance")}
fn main(){let args:Vec<_>=std::env::args().collect();let p=PathBuf::from(&args[1]);let exe=PathBuf::from(&args[2]);let poolroot=PathBuf::from(&args[3]);let rules=format!("sim-w3:{}",args[4]);fs::create_dir(&p).unwrap();let world=p.join("world");
 let resources=[(301,1),(302,1),(303,1),(304,1),(501,4),(502,4),(601,1),(602,1),(603,1),(604,1),(701,2)].into_iter().map(|(id,n)|Resource::new(id,n).unwrap()).collect();
 let mut s=Store::create_spatial_v2(&world,&fs::read(&args[5]).unwrap(),resources,&rules,&fs::read(&args[6]).unwrap(),&fs::read(&args[7]).unwrap()).unwrap();
 apply(&mut s,Action::Timeline{command:T::Enable});
 for use_id in [1,2]{apply_as(&mut s,Caller::Account(3),Action::Venue{use_id,command:V::Accept});let token=s.engine().unwrap().world().view().venue.unwrap().uses.iter().find(|v|v.use_id==use_id).unwrap().token.number;
 apply(&mut s,Action::Venue{use_id,command:V::Enter{event_id:1000+use_id,token_number:token,occurred_at:0}});apply(&mut s,Action::FacilityWork{command:F::Begin{contract_id:use_id}});}
 apply_as(&mut s,Caller::Account(3),Action::ContinuousSupply{command:S::Start{run_id:1,pumps:3}});
 apply(&mut s,a(C::Register{registration:Registration{canonical:70001,resource:701,aliases:[Some(70011),Some(70012),None,None],unit:Unit::Count,owner:1,operator:3,nominal_capacity:2,effective_capacity:2,identity_version:1,policy_version:1,open:true}}));
 for (alias,account,consumer,start,end) in [(70011,3,301,0,10),(70012,4,401,10,20)]{apply(&mut s,a(C::Reserve{alias,account,consumer,consumer_version:1,start,end,units:2}));}
 let mut tokens:Vec<_>=s.engine().unwrap().leases().iter().flatten().filter(|l|l.resource==701).map(|l|l.token).collect();tokens.sort();assert_eq!(tokens.len(),2);drop(s);copy(&world,&p.join("reference"));let mut reference=Store::open(&p.join("reference"),&rules).unwrap();
 let mut pool=normal_pool::Process::spawn(&exe,&poolroot,Some(&p.join("pool-heaps.jsonl"))).unwrap();let mut memory=Vec::new();let mut c=Client::new();c.start_in_pool(&exe,&world,false,false,&poolroot).unwrap();let ready=next(&mut c,&p);assert_eq!(ready.kind,"ready");memory.push(serde_json::to_value(ready).unwrap());
 let entered=remote(&mut c,&p,1,&mut reference,a(C::Enter{token:tokens[0],occurred_at:0}));c.submit(2,Command::Checkpoint).unwrap();assert_eq!(next(&mut c,&p).payload["Ok"]["checkpointed"],true);c.submit(3,Command::Status).unwrap();memory.push(serde_json::to_value(next(&mut c,&p)).unwrap());c.stop().unwrap();
 let mut s=Store::open(&world,&rules).unwrap();assert_eq!(s.state_hash().unwrap(),reference.state_hash().unwrap());let hash=s.state_hash().unwrap();let seq=s.committed_sequence();assert!(s.execute(Caller::System,entered).unwrap().model.is_ok());assert_eq!(s.committed_sequence(),seq);assert_eq!(s.state_hash().unwrap(),hash);assert!(s.engine().unwrap().time_capacity_projection(70011).unwrap().pending_conflict);drop(s);
 c=Client::new();c.start_in_pool(&exe,&world,false,false,&poolroot).unwrap();let ready=next(&mut c,&p);assert_eq!(ready.kind,"ready");memory.push(serde_json::to_value(ready).unwrap());let mut id=100;advance(&mut c,&p,&mut id,&mut reference,10);
 let denied=envelope(&reference,a(C::Enter{token:tokens[1],occurred_at:10}));c.submit(id,Command::Execute{envelope:denied.clone()}).unwrap();id+=1;assert!(next(&mut c,&p).payload["Ok"]["model"].get("Err").is_some());assert!(reference.execute(Caller::System,denied).unwrap().model.is_err());
 remote(&mut c,&p,id,&mut reference,a(C::Exit{token:tokens[0],occurred_at:10}));id+=1;remote(&mut c,&p,id,&mut reference,a(C::Enter{token:tokens[1],occurred_at:10}));id+=1;advance(&mut c,&p,&mut id,&mut reference,25);remote(&mut c,&p,id,&mut reference,a(C::Exit{token:tokens[1],occurred_at:25}));id+=1;
 c.submit(id,Command::Checkpoint).unwrap();assert_eq!(next(&mut c,&p).payload["Ok"]["checkpointed"],true);id+=1;c.submit(id,Command::Status).unwrap();memory.push(serde_json::to_value(next(&mut c,&p)).unwrap());c.stop().unwrap();
 for e in &memory{let v=e["payload"].get("Ok").unwrap_or(&e["payload"]);let snap=&v["runtime"]["allocator_boundary"]["snapshot"];assert_eq!(snap["activation"]["grant_bytes"],59*1024*1024);assert_eq!(snap["allocation_failures"],0);assert!(snap["arena_used_bytes"].as_u64().unwrap()<=snap["arena_usable_bytes"].as_u64().unwrap());}
 let balance=normal_pool::status(&poolroot).unwrap();assert_eq!(balance.workspace_grants,2);assert_eq!(balance.workspace_returns,2);assert_eq!(balance.available_touched_bytes,64*1024*1024);pool.finish().unwrap();let s=Store::open(&world,&rules).unwrap();assert_eq!(s.state_hash().unwrap(),reference.state_hash().unwrap());assert!(!s.engine().unwrap().leases().iter().flatten().any(|l|l.resource==701));
 let view=s.engine().unwrap().world().view();let supply=view.continuous_supply.unwrap();assert_eq!(supply.cursor,25);assert!(supply.raw_used_ml>0);let work=view.facility_work.unwrap();let records:Vec<_>=work.records.iter().flatten().collect();assert_eq!(records.len(),2);assert!(records.iter().all(|r|r.work_seconds==25));
 fs::write(p.join("actual-production.json"),serde_json::to_vec_pretty(&serde_json::json!({"supply":supply,"work":work,"same_original_direct_reference":true,"not_whole_product_precondition":true})).unwrap()).unwrap();
 fs::write(p.join("role-observations.json"),serde_json::to_vec_pretty(&memory).unwrap()).unwrap();fs::write(p.join("pool-return.json"),serde_json::to_vec_pretty(&balance).unwrap()).unwrap();fs::write(p.join("result.json"),serde_json::to_vec_pretty(&serde_json::json!({"two_original_consumers":true,"normal_actual_entry_exit":true,"checkpoint_restart_original_ticket_once":true,"expired_actual_retained_until_exit":true,"same_original_direct_reference":true,"engine_owned_bytes":s.engine().unwrap().owned_capacity_bytes(),"store_owned_bytes":s.owned_capacity_bytes().unwrap(),"test_tool_reference_store_outside_shipping_role":true,"not_whole_game_native_16GB_M0_or_speed":true})).unwrap()).unwrap();
}
